#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

# A wizard calls only some of the library's helpers; the rest stay so every copy matches.
# shellcheck disable=SC2329
set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
	BOLD=$(tput bold)
	DIM=$(tput dim)
	RESET=$(tput sgr0)
	BLUE=$(tput setaf 4)
	GREEN=$(tput setaf 2)
	YELLOW=$(tput setaf 3)
else
	BOLD=""
	DIM=""
	RESET=""
	BLUE=""
	GREEN=""
	YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
	[[ -t 1 ]] || return 0
	if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
	printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
	_clear
	printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
	printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
	printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
	printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
	printf '  later, since it remembers values already saved.%s\n' "$RESET"
	pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
	_clear
	_STAGE_INDEX=$((_STAGE_INDEX + 1))
	printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
		"$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say() { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
	local url="$1"
	printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
	{
		if command -v wslview >/dev/null 2>&1; then
			wslview "$url"
		elif command -v explorer.exe >/dev/null 2>&1; then
			explorer.exe "$url"
		elif command -v xdg-open >/dev/null 2>&1; then
			xdg-open "$url"
		elif command -v open >/dev/null 2>&1; then
			open "$url"
		else false; fi
	} >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
	printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
	read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
	local reply=""
	printf '  %s? %s [y/N] ' "$YELLOW" "$1"
	read -r reply || true
	[[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
	[[ -f "$ENV_FILE" ]] || return 1
	local line value sq="'\\''"
	line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
	value="${line#*=}"
	if [[ "$value" == \'*\' ]]; then
		value="${value:1:${#value}-2}"
		value="${value//"$sq"/\'}"
	elif [[ "$value" == \"*\" ]]; then
		value="${value:1:${#value}-2}"
		[[ "$value" == *[\\\$\"]* ]] && return 1 # escapes, $ or ": can't decode safely; ask again
	fi
	printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
	local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
	current=$(_existing "$key" || true)
	# Readline needs the colour codes wrapped in \001..\002 to place the cursor.
	p="  $s$BOLD$e$prompt$s$RESET$e "
	[[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
	read -e -r -p "$p" input || rc=1
	if ((rc)) && [[ -z "$input" ]]; then return 1; fi
	[[ -z "$input" && -n "$current" ]] && input="$current"
	printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
	local key="$1" prompt="$2" current input rc=0
	current=$(_existing "$key" || true)
	if [[ -n "$current" ]]; then
		printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
	else
		printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
	fi
	read -rs input || rc=1
	printf '\n'
	if ((rc)) && [[ -z "$input" ]]; then return 1; fi
	[[ -z "$input" && -n "$current" ]] && input="$current"
	printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
	local key="$1" value="$2" tmp sq="'\\''"
	[[ -e "$ENV_FILE" ]] || (umask 077 && : >"$ENV_FILE")
	tmp=$(mktemp)
	grep -vE "^${key}=" "$ENV_FILE" >"$tmp" || true
	printf "%s='%s'\n" "$key" "${value//\'/$sq}" >>"$tmp"
	cat "$tmp" >"$ENV_FILE"
	rm -f "$tmp"
	printf -v "$key" '%s' "$value"
	WRITTEN_ENV+=("$key")
	printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
			WRITTEN_SECRET+=("$name")
			printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
			return
		fi
	fi
	SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
	warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
			printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
			return
		fi
	fi
	SKIPPED+=("GitHub variable $name")
	warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
	_clear
	printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
	((${#WRITTEN_ENV[@]})) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
	((${#WRITTEN_SECRET[@]})) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
	if ((${#SKIPPED[@]})); then
		printf '\n'
		warn "still to do by hand:"
		for s in "${SKIPPED[@]}"; do note "  - $s"; done
	fi
	printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

	cd "$(git rev-parse --show-toplevel)"
	# .env*.local is git-ignored, so the token never lands in a commit.
	ENV_FILE=".env.local"
	REPO="Fullchee/journal"
	APP_URL="https://journal.fullchee.workers.dev"
	REDIRECT_URI="http://localhost:8765"
	FALLBACK_DOC="docs/research/fitbit-data.md (Option 4: Health Connect)"
	# Read-only scopes for the sync: sleep, activity and fitness (steps, AZM, exercise), and health metrics (resting HR, HRV, SpO2).
	# Source: https://developers.google.com/health/scopes
	SCOPES="https://www.googleapis.com/auth/googlehealth.sleep.readonly https://www.googleapis.com/auth/googlehealth.activity_and_fitness.readonly https://www.googleapis.com/auth/googlehealth.health_metrics_and_measurements.readonly"
	TEST_URL="https://health.googleapis.com/v4/users/me/dataTypes/steps/dataPoints?pageSize=1"
	NAMES=(GOOGLE_HEALTH_CLIENT_ID GOOGLE_HEALTH_CLIENT_SECRET GOOGLE_HEALTH_REFRESH_TOKEN)

	urlencode() { python3 -I -c 'import sys, urllib.parse; print(urllib.parse.quote(sys.argv[1], safe=""))' "$1"; }
	json_field() { python3 -I -c 'import sys, json; print(json.load(sys.stdin).get(sys.argv[1], ""))' "$1"; }

	# refresh prints Google's reply to a refresh-token exchange; the values go through stdin, not argv.
	refresh() {
		printf 'refresh_token=%s&client_id=%s&client_secret=%s&grant_type=refresh_token' \
			"$(urlencode "$GOOGLE_HEALTH_REFRESH_TOKEN")" "$(urlencode "$GOOGLE_HEALTH_CLIENT_ID")" "$(urlencode "$GOOGLE_HEALTH_CLIENT_SECRET")" |
			curl -sS https://oauth2.googleapis.com/token --data @-
	}

	# stop_expiring_token ends the run: Production didn't stop Google issuing a 7-day token.
	stop_expiring_token() {
		warn "Google says this refresh token expires, even though the app is In production."
		say "A weekly re-consent breaks the hands-off sync, so this route is a dead end."
		say "Switch to the fallback: $FALLBACK_DOC."
		exit 1
	}

	TOTAL_STAGES=8

	banner "Google Health access for the Fitbit sync (#133)"

	stage "Load the saved values"
	for name in "${NAMES[@]}"; do
		value=$(_existing "$name" || true)
		printf -v "$name" '%s' "$value"
		if [[ -n "$value" ]]; then
			printf '  %s✓ found%s %s in %s\n' "$GREEN" "$RESET" "$name" "$ENV_FILE"
		else
			note "missing $name: a later stage asks for it"
		fi
	done
	pause

	stage "Check the refresh token"
	TOKEN_OK=0
	if [[ -n "$GOOGLE_HEALTH_REFRESH_TOKEN" ]]; then
		response=$(refresh)
		if [[ -n "$(json_field access_token <<<"$response")" ]]; then
			TOKEN_OK=1
			printf '  %s✓ Google accepted the refresh token%s\n' "$GREEN" "$RESET"
			granted=$(json_field scope <<<"$response")
			for scope in $SCOPES; do
				[[ " $granted " == *" $scope "* ]] || {
					warn "Not granted: $scope. Stage 6 gets a new token."
					TOKEN_OK=0
				}
			done
			if [[ -n "$(json_field refresh_token_expires_in <<<"$response")" ]]; then
				warn "This token expires in 7 days: the app was in Testing when it was granted."
				TOKEN_OK=0
			fi
		else
			warn "Google refused the token: $(json_field error <<<"$response")"
		fi
	fi
	if ((TOKEN_OK)); then note "Stages 3 to 6 are skipped."; else note "Stages 3 to 6 get a new token."; fi
	pause

	stage "Check your Fitbit data in Google Health"
	if ((TOKEN_OK)); then
		say "Skipped: the saved token works."
	else
		say "The API only sees Fitbit data that lives under your Google Account."
		step "On your phone, open the Google Health app (the old Fitbit app)."
		step "Check it's signed in to your personal Google Account."
		step "Check Today shows last night's sleep and today's steps."
		if ! confirm "Does Google Health show your Fitbit data?"; then
			warn "Link Fitbit to your Google Account first: the API returns ACCOUNT_NOT_LINKED until then."
			open_url "https://support.google.com/fitbit/answer/14236615?hl=en"
			exit 1
		fi
	fi
	pause

	stage "Create a Cloud project and enable the API"
	if ((TOKEN_OK)); then
		say "Skipped: the saved token works."
	elif [[ -n "$GOOGLE_HEALTH_CLIENT_ID" ]]; then
		say "Skipped: a client ID is saved, so the project exists."
	else
		say "Use a new project, not the Calendar one: a verification flag here can't touch Calendar."
		open_url "https://console.cloud.google.com/projectcreate"
		step "Project name: Journal Health. Click Create."
		pause "Press Enter once the project exists."
		open_url "https://console.cloud.google.com/apis/library/health.googleapis.com"
		step "Pick the Journal Health project in the top bar."
		step "Click Enable on Google Health API."
		if ! confirm "Does the API page read API Enabled?"; then
			warn "Enable the Google Health API, then re-run the wizard."
			exit 1
		fi
	fi
	pause

	stage "Set up and publish the OAuth app"
	if ((TOKEN_OK)); then
		say "Skipped: the saved token works."
	else
		say "Testing mode gives tokens that expire after 7 days. Production tokens don't expire."
		note "Keep the Journal Health project picked on every page."
		open_url "https://console.cloud.google.com/auth/branding"
		step "If asked, click Get started. App name: Journal Health. Support email: yours."
		step "Audience: External. Contact email: yours. Agree, then Create."
		step "Home page: $APP_URL. Privacy policy: $APP_URL/privacy.html. Save."
		warn "Empty links block publishing."
		pause "Press Enter once Branding is saved."
		open_url "https://console.cloud.google.com/auth/scopes"
		step "Click Add or remove scopes. Filter by googlehealth and tick these three:"
		for scope in $SCOPES; do note "    ${scope#https://www.googleapis.com/auth/}"; done
		step "Click Update, then Save."
		pause "Press Enter once the scopes are saved."
		open_url "https://console.cloud.google.com/auth/audience"
		step "Test users → Add users → your Google Account → Save."
		step "Click Publish app, then Confirm. Skip any prompt to submit for verification."
		note "Google exempts personal use from verification when you are the only user."
		if ! confirm "Does Publishing status read In production?"; then
			warn "Publish the app first: a Testing-mode token dies in 7 days."
			exit 1
		fi
		if [[ -z "$GOOGLE_HEALTH_CLIENT_ID" || -z "$GOOGLE_HEALTH_CLIENT_SECRET" ]]; then
			open_url "https://console.cloud.google.com/auth/clients/create"
			step "Application type: Web application. Name: Journal Health sync."
			step "Authorized redirect URIs → Add URI → $REDIRECT_URI. Click Create."
			warn "Copy the client secret now: Console hides it once you close the dialog."
			ask GOOGLE_HEALTH_CLIENT_ID "Paste the client ID:"
			ask_secret GOOGLE_HEALTH_CLIENT_SECRET "Paste the client secret:"
			write_env GOOGLE_HEALTH_CLIENT_ID "$GOOGLE_HEALTH_CLIENT_ID"
			write_env GOOGLE_HEALTH_CLIENT_SECRET "$GOOGLE_HEALTH_CLIENT_SECRET"
		fi
		pause
	fi

	stage "Grant health data access"
	if ((TOKEN_OK)); then
		say "Skipped: the saved token works."
	else
		state=$(python3 -I -c 'import secrets; print(secrets.token_urlsafe(16))')
		open_url "https://accounts.google.com/o/oauth2/v2/auth?client_id=$(urlencode "$GOOGLE_HEALTH_CLIENT_ID")&redirect_uri=$(urlencode "$REDIRECT_URI")&response_type=code&scope=$(urlencode "$SCOPES")&access_type=offline&prompt=consent&state=$state"
		step "Pick the Google Account that holds your Fitbit data."
		step "On 'Google hasn't verified this app': Advanced → Go to … (unsafe)."
		step "Tick every health box, then Continue."
		step "The browser lands on a localhost page that fails to load. That's expected."
		step "Copy the full URL from the address bar."
		ask REDIRECTED_URL "Paste the URL:"
		read -r code returned_state < <(python3 -I -c '
import sys, urllib.parse
q = urllib.parse.parse_qs(urllib.parse.urlparse(sys.argv[1]).query)
print(q.get("code", [""])[0], q.get("state", [""])[0])' "$REDIRECTED_URL")
		if [[ -z "$code" || "$returned_state" != "$state" ]]; then
			warn "That URL has no code, or comes from another attempt. Re-run the wizard."
			exit 1
		fi
		response=$(curl -sS https://oauth2.googleapis.com/token \
			--data-urlencode "code=$code" \
			--data-urlencode "client_id=$GOOGLE_HEALTH_CLIENT_ID" \
			--data-urlencode "client_secret=$GOOGLE_HEALTH_CLIENT_SECRET" \
			--data-urlencode "redirect_uri=$REDIRECT_URI" \
			--data-urlencode "grant_type=authorization_code")
		refresh_token=$(json_field refresh_token <<<"$response")
		if [[ -z "$refresh_token" ]]; then
			warn "Google returned no refresh token: $(json_field error_description <<<"$response")"
			exit 1
		fi
		write_env GOOGLE_HEALTH_REFRESH_TOKEN "$refresh_token"
		if [[ -n "$(json_field refresh_token_expires_in <<<"$response")" ]]; then stop_expiring_token; fi
		printf '  %s✓ The token has no expiry: Production worked.%s\n' "$GREEN" "$RESET"
		pause
	fi

	stage "Read one Fitbit data point"
	access_token=$(refresh | json_field access_token)
	if [[ -z "$access_token" ]]; then
		warn "Google refused the saved token. Re-run the wizard to get a new one."
		exit 1
	fi
	response=$(printf 'Authorization: Bearer %s\n' "$access_token" | curl -sS -H @- "$TEST_URL")
	if [[ "$response" == *ACCOUNT_NOT_LINKED* ]]; then
		warn "ACCOUNT_NOT_LINKED: your Fitbit account isn't linked to this Google Account."
		step "Move Fitbit to your Google Account in the Google Health app, then re-run."
		open_url "https://support.google.com/fitbit/answer/14236615?hl=en"
		exit 1
	fi
	count=$(python3 -I -c '
import sys, json
reply = json.load(sys.stdin)
print(-1 if "error" in reply else len(reply.get("dataPoints", [])))' <<<"$response")
	if ((count < 0)); then
		warn "The Google Health API refused the call: $(python3 -I -c 'import sys, json; print(json.load(sys.stdin)["error"].get("message", ""))' <<<"$response")"
		exit 1
	elif ((count == 0)); then
		warn "The call worked but returned no steps. Wear the Fitbit for a day, then re-run to check."
	else
		printf '  %s✓ Read a steps data point from Fitbit%s\n' "$GREEN" "$RESET"
	fi
	pause

	stage "Store the secrets on GitHub"
	say "The sync runs as a GitHub Action, so it reads these from repo secrets."
	if confirm "Set ${NAMES[*]} on $REPO?"; then
		# The active gh account is the work one, which can't write to Fullchee/*.
		gh_token=$(gh auth token --user Fullchee)
		for name in "${NAMES[@]}"; do
			if printf '%s' "${!name}" | GH_TOKEN="$gh_token" gh secret set "$name" --repo "$REPO" >/dev/null; then
				printf '  %s✓ set%s repo secret %s\n' "$GREEN" "$RESET" "$name"
			else
				SKIPPED+=("repo secret $name (gh secret set $name --repo $REPO)")
			fi
		done
	else
		SKIPPED+=("repo secrets: re-run the wizard and say yes at stage 8")
	fi

	finish
	say "Next: tell Claude \"the Health token works\" to start the Fitbit push scripts."
}

run_wizard "$@"
exit
